const { ethers } = require("ethers");
require("dotenv").config();
const { decideChains } = require("../../../config/provider");

const PHANTOM_ADDRESS = "0x0000000000000000000000000000000000008888";
// Bytecode compiled with evm_version = 'paris'
const HONEYPOT_BYTECODE =
  "";

const ROUTERS = {
  1: "0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D", // uniswapV2
};

const HONEYPOT_ABI = [
  {
    inputs: [
      { internalType: "address", name: "targetContract", type: "address" },
      { internalType: "address", name: "dexRouter", type: "address" },
    ],
    name: "checkContract",
    outputs: [
      {
        components: [
          { internalType: "bool", name: "isBlackListDetected", type: "bool" },
          { internalType: "bool", name: "isMintable", type: "bool" },
          { internalType: "uint256", name: "mintScore", type: "uint256" },
          { internalType: "string", name: "mintReason", type: "string" },
          { internalType: "bool", name: "isTradingControl", type: "bool" },
          { internalType: "uint256", name: "buyTax", type: "uint256" },
          { internalType: "uint256", name: "sellTax", type: "uint256" },
          { internalType: "uint8", name: "riskScore", type: "uint8" },
          { internalType: "string", name: "errorReason", type: "string" },
        ],
        internalType: "struct HoneypotBase.HoneypotBaseResult",
        name: "",
        type: "tuple",
      },
    ],
    stateMutability: "payable",
    type: "function",
  },
];

const iface = new ethers.Interface(HONEYPOT_ABI);

const _runHoneypotCheck = async (targetContract, chainId = 1) => {
  try {
    const provider = decideChains("ETH");
    const dexRouterAddress = ROUTERS[chainId] || ROUTERS[1];

    const callData = iface.encodeFunctionData("checkContract", [
      targetContract,
      dexRouterAddress,
    ]);

    // Used Vitalik's address here. Sending zero-history empty accounts to
    // some security-checked tokens will automatically revert them.
    const TEST_SENDER = "0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045";

    const stateOverride = {
      [PHANTOM_ADDRESS]: {
        code: HONEYPOT_BYTECODE,
        balance: ethers.toBeHex(ethers.parseEther("100")),
      },
      [TEST_SENDER]: {
        balance: ethers.toBeHex(ethers.parseEther("100")),
      },
    };

    const intervals = [
      { label: "Immediate", delay: 0 },
      { label: "24 Hours", delay: 86400 },
      { label: "7 Days", delay: 604800 },
    ];

    let finalResult = {
      riskScore: 0,
      hasBlackListDetected: false,
      hasMintable: false,
      mintScore: 0,
      mintReason: "",
      hasTradingControl: false,
      buyingTax: 0,
      sellingTax: 0,
      errorReason: "",
      isTimeHoneypot: false,
      timeTravelResults: [],
    };

    const now = Math.floor(Date.now() / 1000);

    for (const interval of intervals) {
      const futureTimestamp = now + interval.delay;

      const txObj = {
        from: TEST_SENDER,
        to: PHANTOM_ADDRESS,
        data: callData,
        gas: "0x1C9C380", // 30,000,000 gas
      };

      const params = [txObj, "latest", stateOverride];

      if (interval.delay > 0) {
        params.push({
          // CRITICAL FIX: The key is timestamp, NOT time.
          timestamp: ethers.toBeHex(futureTimestamp),
        });
      }

      try {
        const response = await provider.send("eth_call", params);

        if (!response || response === "0x") {
          throw new Error(
            "Empty response from node (possibly reverted without data)",
          );
        }

        const decoded = iface.decodeFunctionResult(
          "checkContract",
          response,
        )[0];

        const result = {
          label: interval.label,
          riskScore: Number(decoded.riskScore),
          buyTax: Number(decoded.buyTax),
          sellTax: Number(decoded.sellTax),
          isTradingControl: decoded.isTradingControl,
          errorReason: decoded.errorReason,
        };

        finalResult.timeTravelResults.push(result);

        if (interval.delay === 0) {
          finalResult.riskScore = result.riskScore;
          finalResult.hasBlackListDetected = decoded.isBlackListDetected;
          finalResult.hasMintable = decoded.isMintable;
          finalResult.mintScore = Number(decoded.mintScore);
          finalResult.mintReason = decoded.mintReason;
          finalResult.hasTradingControl = decoded.isTradingControl;
          finalResult.buyingTax = result.buyTax;
          finalResult.sellingTax = result.sellTax;
          finalResult.errorReason = decoded.errorReason;
        } else {
          if (
            result.riskScore > finalResult.riskScore ||
            result.buyTax > finalResult.buyingTax + 10 ||
            result.sellTax > finalResult.sellingTax + 10
          ) {
            finalResult.isTimeHoneypot = true;
            finalResult.riskScore = Math.max(
              finalResult.riskScore,
              result.riskScore,
            );
          }
        }
      } catch (err) {
        console.warn(
          `[TxShield] Time Travel (${interval.label}) Failed:`,
          err.message,
        );

        finalResult.timeTravelResults.push({
          label: interval.label,
          error: err.message,
        });

        // CIRCUIT BREAKER: If the immediate check fails with a hard revert, the token is dead.
        // Stop the loop and flag it immediately.
        if (interval.delay === 0) {
          finalResult.riskScore = 100;
          finalResult.errorReason = `Fatal Simulation Error: Contract is dead, has 0 liquidity, or contains hard revert traps. (${err.message})`;
          break; // <--- This saves your Alchemy Compute Units.
        }
      }
    }

    return finalResult;
  } catch (err) {
    console.error(`Honeypot Fatal Error: ${err.message}`);
    throw err;
  }
};

module.exports = _runHoneypotCheck;
